# -*- coding: utf-8 -*-
"""用赛狐已发货单探测：BLACKCAT vs 昇新 是否出现在金猫 WMS。"""
import datetime
import yaml
from bridge.clients.sellfox import SellfoxClient
from bridge.clients.wms import WmsClient, WmsError

with open("config/config.yaml", encoding="utf-8") as f:
    cfg = yaml.safe_load(f)

sf = SellfoxClient(cfg["sellfox"]["base_url"], cfg["sellfox"]["client_id"], cfg["sellfox"]["client_secret"])
wms = WmsClient(cfg["wms"]["base_url"], cfg["wms"]["key"], cfg["wms"]["api_secret"])

end = datetime.datetime.now()
start = end - datetime.timedelta(days=7)

def pull(status, limit_pages=3):
    out = []
    for page in range(1, limit_pages + 1):
        data = sf.get_package_page(
            status,
            start.strftime("%Y-%m-%d %H:%M:%S"),
            end.strftime("%Y-%m-%d %H:%M:%S"),
            page_no=page,
            shop_ids=cfg["run"]["shop_whitelist"],
        )
        rows = (data or {}).get("rows") or []
        out.extend(rows)
        if page >= (data or {}).get("totalPage", 1):
            break
    return out

# try has_shipped first
for status in ("has_shipped", "shipped", "to_print", "apply_track_no"):
    try:
        rows = pull(status, 2)
        print(f"status={status}  count_this_pull={len(rows)}  totalPage sample ok")
        if rows:
            break
    except Exception as e:
        print(f"status={status}  ERR {e}")
        rows = []

print(f"\n使用状态={status if 'status' in dir() else '?'} 样本数={len(rows)}\n")

# classify
bc, sh = [], []
for p in rows:
    ch = ((p.get("logistics") or {}).get("channelName") or "")
    sn = p.get("packageSn")
    if "BLACKCAT" in ch.upper():
        bc.append((sn, ch))
    elif ch:
        sh.append((sn, ch))

print(f"本批 BLACKCAT={len(bc)}  昇新类={len(sh)}")

def probe(label, samples, n=5):
    print(f"\n--- {label} 抽 {min(n,len(samples))} 单查金猫 WMS ---")
    found = miss = 0
    for sn, ch in samples[:n]:
        try:
            st = wms.query_order_status(sn) or {}
            try:
                tn = wms.query_tracking_number(sn) or {}
            except Exception as e:
                tn = {"_err": str(e)}
            print(f"  FOUND {sn} ch={ch} orderStatus={st.get('orderStatus')} "
                  f"express={tn.get('express')} track={tn.get('trackingNumber')}")
            found += 1
        except WmsError as e:
            print(f"  MISS  {sn} ch={ch}  ({e})")
            miss += 1
        except Exception as e:
            print(f"  ERR   {sn}  {e}")
            miss += 1
    print(f"  => found={found} miss={miss}")
    return found, miss

probe("BLACKCAT", bc, 6)
probe("昇新/其它", sh, 6)

