def step1b_sync_ordered(self):
    """A3 幂等：赛狐已是物流下单/已发货的包裹，本地提前同步为 ORDERED，
    避免对已下单包裹再次 applyTrackNo。"""
    if not self._run_cfg().get("auto_apply_track_no") and not self.dry_run:
        # dry-run 也同步状态，便于观察；无 auto 时仍可同步，减少状态漂移
        pass
    synced = 0
